/**
 * Turns the vendored `details()` manifests into three generated files:
 *
 *   src/catalog/data.generated.ts       the runtime catalog (browser-safe data)
 *   src/catalog/inputs.generated.ts     types only, fully erased at run time
 *   src/catalog/factories.generated.ts  one typed factory function per plugin
 *
 * Everything here hard-errors rather than papering over surprises. A plugin that
 * fails to evaluate, a non-string `defaultValue`, or an `overrides.ts` key that
 * no longer resolves all stop the build - the point is that the generated data
 * cannot silently drift from upstream.
 *
 * Run via `pnpm catalog:generate`; `pnpm catalog:check` asserts the committed
 * files still match.
 */

import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  ERROR_CAPABLE,
  FLOW_ENDING,
  PASSTHROUGH_INPUTS,
  TERMINAL_OVERRIDE,
} from '../src/catalog/overrides.ts';
import { discoverPlugins } from '../src/node/discover.ts';
import { vendorInfo } from '../src/node/vendor.ts';
import type { CatalogEntry, CatalogInput } from '../src/types/catalog.ts';
import { packageRoot } from './plugin-repo.ts';

const HEADER = '// @generated by scripts/generate-catalog.ts - do not edit.\n';

// --- normalisation ----------------------------------------------------------

/**
 * Tooltips are authored as indented template literals in the plugin source, so
 * they arrive with the source file's leading whitespace baked into every line.
 * Strip it; keep the line breaks, because several tooltips are bulleted lists
 * that only read correctly multi-line.
 */
function cleanTooltip(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  const lines = raw.replace(/\r\n/g, '\n').split('\n').map((line) => line.trimEnd());
  while (lines.length && lines[0]!.trim() === '') lines.shift();
  while (lines.length && lines.at(-1)!.trim() === '') lines.pop();
  if (!lines.length) return undefined;

  const indents = lines.filter((l) => l.trim() !== '').map((l) => l.length - l.trimStart().length);
  const dedent = Math.min(...indents);
  return lines.map((l) => l.slice(dedent)).join('\n');
}

function toCatalogInput(pluginRef: string, raw: unknown): CatalogInput {
  const input = raw as Record<string, any>;

  // The whole string-coercion model rests on this. `loadDefaultValues` reads
  // every value out of inputsDB as a string, so a non-string default would mean
  // the SDK's encode/decode contract is wrong somewhere.
  if (typeof input['defaultValue'] !== 'string') {
    throw new Error(
      `${pluginRef}: input "${input['name']}" has a ${typeof input['defaultValue']} defaultValue `
        + `(${JSON.stringify(input['defaultValue'])}). Every default in the catalog has always `
        + 'been a string; if upstream changed that, src/graph/inputs.ts needs revisiting first.',
    );
  }

  const ui = (input['inputUI'] ?? { type: 'text' }) as Record<string, any>;
  const result: CatalogInput = {
    name: String(input['name']),
    label: String(input['label'] ?? input['name']),
    type: input['type'] as CatalogInput['type'],
    defaultValue: input['defaultValue'],
    ui: {
      type: String(ui['type'] ?? 'text'),
      ...(Array.isArray(ui['options']) ? { options: ui['options'].map(String) } : {}),
    },
  };
  const tooltip = cleanTooltip(input['tooltip']);
  if (tooltip) result.tooltip = tooltip;
  if (ui['displayConditions']) result.displayConditions = ui['displayConditions'];
  return result;
}

function buildEntries(): CatalogEntry[] {
  const discovered = discoverPlugins();
  const seenOverrides = new Set<string>();

  const entries = discovered.map(({ category, name, version, ref, details }): CatalogEntry => {
    const errorOverride = ERROR_CAPABLE[ref];
    if (errorOverride) seenOverrides.add(ref);

    const outputs = (details.outputs ?? []).map((o) => {
      const tooltip = cleanTooltip(o.tooltip);
      return tooltip ? { number: o.number, tooltip } : { number: o.number };
    });

    const entry: CatalogEntry = {
      ref,
      name,
      version,
      title: details.name,
      description: (details.description ?? '').trim(),
      category,
      tags: (details.tags ?? '').split(',').map((t) => t.trim()).filter(Boolean),
      isStartPlugin: Boolean(details.isStartPlugin),
      inputs: (details.inputs ?? []).map((i) => toCatalogInput(ref, i)),
      outputs,
      error: Boolean(errorOverride),
      errorConfidence: errorOverride?.confidence ?? 'observed',
      terminal: TERMINAL_OVERRIDE[ref] ?? outputs.length === 0,
      flowEnding: ref in FLOW_ENDING,
      passthroughInputs: ref in PASSTHROUGH_INPUTS,
    };
    if (details.requiresVersion) entry.requiresVersion = details.requiresVersion;
    if (details.icon) entry.icon = details.icon;
    if (details.style?.borderColor) entry.borderColor = String(details.style.borderColor);
    return entry;
  });

  // A stale override is the failure mode this whole file exists to prevent: it
  // would leave the linter quietly reasoning about a plugin that no longer
  // exists under that name.
  const stale = [
    ...Object.keys(ERROR_CAPABLE).filter((ref) => !seenOverrides.has(ref)),
    ...Object.keys(TERMINAL_OVERRIDE).filter((ref) => !entries.some((e) => e.ref === ref)),
    ...Object.keys(FLOW_ENDING).filter((ref) => !entries.some((e) => e.ref === ref)),
    ...Object.keys(PASSTHROUGH_INPUTS).filter((ref) => !entries.some((e) => e.ref === ref)),
  ];
  if (stale.length) {
    throw new Error(
      `src/catalog/overrides.ts references plugins that are no longer vendored:\n`
        + stale.map((r) => `  ${r}`).join('\n')
        + '\n\nEither upstream renamed them or the vendored tree is out of date. '
        + 'Fix the keys, do not just delete them - each records why the plugin can fail.',
    );
  }

  return entries;
}

// --- emitters ---------------------------------------------------------------

/** JSON, but as TS source: stable key order and no trailing whitespace. */
function literal(value: unknown, indent = 0): string {
  const pad = '  '.repeat(indent);
  if (value === undefined) return 'undefined';
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) {
    if (!value.length) return '[]';
    return `[\n${value.map((v) => `${pad}  ${literal(v, indent + 1)}`).join(',\n')}\n${pad}]`;
  }
  const keys = Object.keys(value as object).filter((k) =>
    (value as Record<string, unknown>)[k] !== undefined
  );
  if (!keys.length) return '{}';
  const body = keys
    .map((k) => `${pad}  ${JSON.stringify(k)}: ${literal((value as any)[k], indent + 1)}`)
    .join(',\n');
  return `{\n${body}\n${pad}}`;
}

function emitData(entries: CatalogEntry[]): string {
  const info = vendorInfo();
  if (!info) throw new Error('vendor/VERSION.json is missing - run `pnpm plugins:update`');

  return `${HEADER}//
// ${entries.length} plugins from ${info.repo}@${info.sha.slice(0, 10)}.
// Keyed by \`name@version\`: seven plugins ship two versions and the version
// changes their output count, so name alone is not a key.

import type { Catalog } from '../types/catalog.ts';

export const CATALOG: Catalog = ${
    literal({
      generatedFrom: { repo: info.repo, sha: info.sha, committedAt: info.committedAt },
      entries,
    })
  };
`;
}

/** `1 | 2 | 6 | 8` from a numeric dropdown, `'aac' | 'eac3'` from a string one. */
function inputType(input: CatalogInput): string {
  const options = input.ui.options?.filter((o) => o !== '');
  if (options?.length) {
    if (input.type === 'number') {
      const numbers = options.map(Number);
      if (numbers.every((n) => Number.isFinite(n))) return [...new Set(numbers)].join(' | ');
    } else if (input.type === 'string') {
      return [...new Set(options)].map((o) => JSON.stringify(o)).join(' | ');
    }
  }
  return input.type === 'boolean' ? 'boolean' : input.type === 'number' ? 'number' : 'string';
}

function emitInputs(entries: CatalogEntry[]): string {
  const inputs = entries.map((e) => {
    if (!e.inputs.length) return `  ${JSON.stringify(e.ref)}: Record<string, never>;`;
    const fields = e.inputs
      .map((i) => `    ${/^[A-Za-z_$][\w$]*$/.test(i.name) ? i.name : JSON.stringify(i.name)}?: ${inputType(i)};`)
      .join('\n');
    return `  ${JSON.stringify(e.ref)}: {\n${fields}\n  };`;
  }).join('\n');

  const handles = entries.map((e) => {
    const numbers = e.outputs.map((o) => o.number);
    return `  ${JSON.stringify(e.ref)}: ${numbers.length ? numbers.join(' | ') : 'never'};`;
  }).join('\n');

  const errors = entries.filter((e) => e.error)
    .map((e) => `  ${JSON.stringify(e.ref)}: true;`).join('\n');

  return `${HEADER}//
// Types only - this file is fully erased at run time.
//
// Every field is optional: Tdarr's \`loadDefaultValues\` fills any key missing
// from \`inputsDB\` with the plugin's own default, so omitting one is meaningful
// and correct rather than a hole.

export interface PluginInputs {
${inputs}
}

/** Numbered output handles each plugin exposes. \`never\` means it is terminal. */
export interface PluginHandles {
${handles}
}

/**
 * Plugins with an \`err1\` handle. Hand-curated in \`catalog/overrides.ts\` -
 * \`details()\` does not report this.
 */
export interface PluginErrorHandle {
${errors}
}

/** \`\${pluginName}@\${version}\` for every catalogued plugin. */
export type PluginRef = keyof PluginInputs;

export type InputsFor<R extends PluginRef> = PluginInputs[R];

export type HandlesFor<R extends PluginRef> = R extends keyof PluginHandles ? PluginHandles[R]
  : number;

export type HasError<R extends PluginRef> = R extends keyof PluginErrorHandle ? true : false;
`;
}

/**
 * A plugin's factory is named after its directory. Where two versions exist the
 * newest gets the bare name and older ones a `V<major>` suffix, so
 * `compareFileSizeRatio()` means "the current one" and stays meaningful when
 * upstream adds a 3.0.0.
 */
function factoryNames(entries: CatalogEntry[]): Map<string, string> {
  const byName = new Map<string, CatalogEntry[]>();
  for (const e of entries) {
    const list = byName.get(e.name) ?? [];
    list.push(e);
    byName.set(e.name, list);
  }

  const names = new Map<string, string>();
  for (const [name, versions] of byName) {
    versions.sort((a, b) => a.version.localeCompare(b.version, undefined, { numeric: true }));
    const identifier = /^[A-Za-z_$][\w$]*$/.test(name) ? name : `plugin_${name}`;
    for (const entry of versions) {
      const isLatest = entry === versions.at(-1);
      names.set(
        entry.ref,
        isLatest ? identifier : `${identifier}V${entry.version.split('.')[0]}`,
      );
    }
  }
  return names;
}

/**
 * Three upstream names are misspelled (`Rorder`, `Vdeo` twice) and one is
 * capitalised inconsistently. The canonical export has to keep the wrong
 * spelling because it must match `FlowNode.pluginName`, but an alias spares
 * every caller from having to remember the typo.
 */
const ALIASES: Record<string, string> = {
  ffmpegCommandRorderStreams: 'ffmpegCommandReorderStreams',
  ffmpegCommandSetVdeoFramerate: 'ffmpegCommandSetVideoFramerate',
  ffmpegCommandSetVdeoResolution: 'ffmpegCommandSetVideoResolution',
  CheckVideoFramerate: 'checkVideoFramerate',
};

function emitFactories(entries: CatalogEntry[]): string {
  const names = factoryNames(entries);

  const factories = entries.map((e) => {
    const fn = names.get(e.ref)!;
    const ref = JSON.stringify(e.ref);
    return `/** ${e.title}${e.outputs.length ? ` - ${e.outputs.length} output(s)` : ' - terminal'}${
      e.error ? ', has err1' : ''
    } */\nexport const ${fn} = (\n  inputs?: InputsFor<${ref}>,\n  options?: NodeOptions,\n): NodeSpec<${ref}> => node(${ref}, inputs, options);`;
  }).join('\n\n');

  const aliases = Object.entries(ALIASES)
    .filter(([wrong]) => entries.some((e) => e.name === wrong))
    .map(([wrong, right]) =>
      `/** Alias for \`${wrong}\` - the upstream plugin name is misspelled, and\n`
      + ` * the canonical export has to keep the typo because it must match\n`
      + ` * \`FlowNode.pluginName\` exactly. */\nexport const ${right} = ${wrong};`
    ).join('\n\n');

  return `${HEADER}//
// One typed factory per catalogued plugin. The newest version of a plugin gets
// the bare name; older versions are suffixed (\`compareFileSizeRatioV1\`).

import { node } from '../graph/builder.ts';
import type { NodeOptions, NodeSpec } from '../graph/builder.ts';
import type { InputsFor } from './inputs.generated.ts';

${factories}

// --- aliases for upstream typos ---------------------------------------------

${aliases}
`;
}

// --- entry point ------------------------------------------------------------

export function generate(): Record<string, string> {
  const entries = buildEntries();
  return {
    'data.generated.ts': emitData(entries),
    'inputs.generated.ts': emitInputs(entries),
    'factories.generated.ts': emitFactories(entries),
  };
}

if (import.meta.filename === process.argv[1]) {
  const files = generate();
  const dir = join(packageRoot, 'src', 'catalog');
  for (const [name, content] of Object.entries(files)) {
    writeFileSync(join(dir, name), content);
    console.log(`wrote src/catalog/${name} (${content.length.toLocaleString()} bytes)`);
  }
}
